package glitch

import data.glitch_lib

switch_types := {"SWITCH", "switch", "Switch", "case", "match"}

has_default_case(conditions) {
    some cond in conditions
    cond.is_default == true
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    conditions := glitch_lib.all_conditional_statements(parent)
    node := conditions[_]

    # Check if it's a switch-type conditional statement
    node.type == 2  # ConditionalStatement.ConditionType.SWITCH

    # Get all conditional statements in the same switch block
    switch_conditions := {c |
        conditions[_] = c
        same_switch_block(node, c)
    }

    # Check if there's no default case
    not has_default_case(switch_conditions)

    result := {
        "type": "sec_no_default_switch",
        "element": node,
        "path": parent.path,
        "description": "Missing default case in multiple condition expression - Switch statements should have a default case to handle unexpected values. (CWE-478)"
    }
}

# Helper to determine if conditional statements belong to the same switch block
same_switch_block(a, b) {
    # Same line range indicates same switch structure
    a.line <= b.line
    a.end_line >= b.end_line
} else {
    b.line <= a.line
    b.end_line >= a.end_line
}

