package glitch

import data.glitch_lib
import future.keywords.in

# Helper to check if a conditional represents a value expression context (selector)
# This is when the ConditionalStatement appears as a value in a Variable or Attribute
is_value_context(node) {
    walk(input, [path, parent])
    parent.ir_type == "Variable"
    parent.value == node
} else {
    walk(input, [path, parent])
    parent.ir_type == "Attribute"
    parent.value == node
}

# Collect all nodes in a switch chain via walk (avoids recursion)
collect_switch_nodes(root) = nodes {
    nodes := {n |
        walk(root, [_, n])
        n.ir_type == "ConditionalStatement"
        n.type == "SWITCH"
    }
}

# Check if any node in the switch chain is a default case
has_default_case(root) {
    node := collect_switch_nodes(root)[_]
    node.is_default == true
}

# A "statement-level" switch is one that is NOT in a value expression context
is_statement_switch(switch) {
    not is_value_context(switch)
}

# Find all top-level statement switches (where the chain starts)
all_statement_switches(node) = switches {
